<template><PageShell title="Detalhes do paciente"><div v-if="patient" class="space-y-5"><section class="panel"><h2 class="section-title">{{patient.full_name}}</h2><p>{{patient.phone}} · {{patient.email||'Sem e-mail'}} · Nascimento: {{date(patient.birth_date)}}</p></section><section class="panel"><h2 class="section-title">Convênios</h2><p v-for="i in patient.insurances" :key="i.id">{{i.insurance_name}} — {{i.card_number}} <span class="text-gray-500">({{i.active?'ativo':'inativo'}})</span></p><p v-if="!patient.insurances.length" class="text-gray-500">Nenhum convênio cadastrado.</p></section><section class="panel"><h2 class="section-title">Processos anteriores</h2><RouterLink v-for="p in patient.processes" :key="p.id" :to="`/central-de-guias/${p.id}`" class="block border-b py-3">Avaliação em {{date(p.assessment_date)}} — {{p.treatment_status}}</RouterLink></section></div></PageShell></template>
<script setup lang="ts">/* eslint-disable @typescript-eslint/no-explicit-any */import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import api from '@/plugins/axios';import PageShell from '@/components/PageShell.vue';const patient=ref<any>();const route=useRoute();const date=(v:string)=>v?new Date(v).toLocaleDateString('pt-BR'):'—';onMounted(async()=>patient.value=(await api.get(`/patients/${route.params.id}`)).data);</script>
